head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLastJob = "";
scwin.edu_schdl_id = frame.opener.key_edu_schdl_id;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        frame.width = 600;
        frame.height = 300;

        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.setCode();
        if (scwin.edu_schdl_id !== "") {
            await scwin.readInfo();
            cmb_CHRG_TP_CD.setDisabled(true);
        } else {
            await scwin.setHeader();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30617.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30617.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete_onclick = function() {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30617.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30617.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_EDU_STRT_DD_onclick
 * @description img_EDU_STRT_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDU_STRT_DD_onclick = function() {
    try {
        popUpCalendar2(edt_EDU_STRT_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30617.img_EDU_STRT_DD_onclick" });
    }
};

/**
 * @method
 * @name img_EDU_END_DD_onclick
 * @description img_EDU_END_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDU_END_DD_onclick = function() {
    try {
        popUpCalendar2(edt_EDU_END_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30617.img_EDU_END_DD_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await scwin.alert_error2(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30617.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        await $c.win.alert(msg);
        // var fr_fn_Search = frame.Provider("../").fn_Search;
        const fr_fn_Search = $c.frame.path("../").fn_Search_Page;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30617.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_edu",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_edu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_MASTER.insertRow();
};

/**
 * @method
 * @name readInfo
 * @description read Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readInfo = async function() {
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (cmb_CHRG_TP_CD.getValue() === '') {
        await $c.win.alert("[담당자구분]을 선택하세요.");
        cmb_CHRG_TP_CD.focus();
        return;
    }
    if (cmb_edu.getValue() === '') {
        await $c.win.alert("[교육구분]을 입력하세요.");
        cmb_edu.focus();
        return;
    }
    if (txb_EDU_CRS_NM.getValue() === '') {
        await $c.win.alert("[교육과정명]을 입력하세요.");
        txb_EDU_CRS_NM.focus();
        return;
    }
    if (txb_EDU_TM.getValue() === '') {
        await $c.win.alert("[교육시간]을 입력하세요.");
        txb_EDU_TM.focus();
        return;
    }
    if (txb_EDU_ACK_TM.getValue() === '') {
        await $c.win.alert("[이수기준(인정시간)]을 입력하세요.");
        txb_EDU_ACK_TM.focus();
        return;
    }
    if (edt_EDU_STRT_DD.getValue() === '') {
        await $c.win.alert("[교육일정]을 입력하세요.");
        edt_EDU_STRT_DD.focus();
        return;
    }
    if (txb_EDU_INST_NM.getValue() === '') {
        await $c.win.alert("[교육기관명]을 입력하세요.");
        txb_EDU_INST_NM.focus();
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        // setObjectValue(txb_acpt_ddtm,"");
        scwin.gLastJob = "저장";
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ListedCompany.do",
            ref : "dts_MASTER",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {void}
 * @hidden N
 */
scwin.delete = function() {
    if (window.confirm("[삭제]하시겠습니까?")) {
        scwin.gLastJob = "삭제";
        txb_EDU_TM.setValue("");
        const url = "/ListedCompany.do?method=deleteDisclsEduSchdl&EDU_SCHDL_ID=" + scwin.edu_schdl_id + "&SCREN_ID=" + "ULDSTF30617.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_MASTER)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name alert_error2
 * @description alert error2 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
